@page "/apply"
@rendermode InteractiveServer
@using sv_cd10ee3541f14e8ebdc190f4cd11ef6c.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h2 class="mb-4">Job Application</h2>

<StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps" OnStepClicked="GoToStep" />

<div class="mt-4">
    @if (submitted)
    {
        <div class="alert alert-success text-center" role="alert">
            <h4 class="alert-heading">Application Submitted!</h4>
            <p>Your application has been received. Your application ID is:</p>
            <p class="display-6 fw-bold">@applicationId</p>
        </div>
    }
    else
    {
        @switch (currentStep)
        {
            case 1:
                <StepPersonalInfo FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                    FullNameChanged="v => fullName = v" EmailChanged="v => email = v"
                    PhoneChanged="v => phone = v" AddressChanged="v => address = v"
                    OnNext="HandlePersonalInfoNext" />
                break;
            case 2:
                <StepWorkHistory Entries="workEntries" OnBack="GoBack" OnNext="GoNext" />
                break;
            case 3:
                <StepReferences References="references" OnBack="GoBack" OnNext="GoNext" />
                break;
            case 4:
                <StepCoverLetter @bind-Text="coverLetter" OnBack="GoBack" OnNext="GoNext" />
                break;
            case 5:
                <StepReview FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                    WorkEntries="workEntries" References="references" CoverLetter="@coverLetter"
                    OnEdit="GoToStep" OnSubmit="HandleSubmit" OnBack="GoBack"
                    IsSubmitting="isSubmitting" />
                break;
        }

        @if (!string.IsNullOrEmpty(errorMessage))
        {
            <div class="alert alert-danger mt-3" role="alert">@errorMessage</div>
        }
    }
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();
    private bool submitted;
    private bool isSubmitting;
    private int applicationId;
    private string? errorMessage;

    // Step 1
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2
    private List<WorkEntryModel> workEntries = new() { new() };

    // Step 3
    private List<ReferenceModel> references = new() { new(), new() };

    // Step 4
    private string coverLetter = "";

    private async Task HandlePersonalInfoNext()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email)
            || string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            errorMessage = "All fields are required.";
            return;
        }

        var emailValid = await ApplicationService.ValidateEmailAsync(email);
        if (!emailValid)
        {
            errorMessage = "Please enter a valid email address.";
            return;
        }

        completedSteps.Add(1);
        currentStep = 2;
    }

    private void GoNext()
    {
        errorMessage = null;
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void GoBack()
    {
        errorMessage = null;
        currentStep--;
    }

    private void GoToStep(int step)
    {
        if (step < currentStep || completedSteps.Contains(step))
        {
            errorMessage = null;
            currentStep = step;
        }
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        errorMessage = null;

        try
        {
            var personal = new PersonalInfo(fullName, email, phone, address);
            var work = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, work, refs, coverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            submitted = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@using static sv_cd10ee3541f14e8ebdc190f4cd11ef6c.Components.Pages.Apply.Apply

<h4>References</h4>

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    var r = References[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Reference @(index + 1)</h6>
                @if (References.Count > 2)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="row mb-2">
                <div class="col-md-6">
                    <label class="form-label">Name</label>
                    <input type="text" class="form-control" @bind="r.Name" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Relationship</label>
                    <input type="text" class="form-control" @bind="r.Relationship" />
                </div>
            </div>
            <div class="row mb-2">
                <div class="col-md-6">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="r.Email" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Phone</label>
                    <input type="tel" class="form-control" @bind="r.Phone" />
                </div>
            </div>
        </div>
    </div>
}

@if (References.Count < 3)
{
    <button class="btn btn-outline-primary mb-3" @onclick="AddReference">Add Reference</button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="OnNext">Next</button>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private void AddReference() => References.Add(new());

    private void RemoveReference(int index) => References.RemoveAt(index);
}

