{"file_text": "<div class="d-flex justify-content-between align-items-center mb-2">
    @for (int i = 0; i < stepNames.Length; i++)
    {
        var step = i + 1;
        var isCompleted = CompletedSteps.Contains(step);
        var isCurrent = step == CurrentStep;
        var isClickable = isCompleted && !isCurrent;

        <div class="text-center flex-fill position-relative">
            <button type="button" disabled="@(!isClickable)"
                class="btn rounded-circle @(isCurrent ? "btn-primary" : isCompleted ? "btn-success" : "btn-secondary") d-inline-flex align-items-center justify-content-center"
                style="width:36px;height:36px;font-size:0.85rem;"
                @onclick="() => OnStepClicked.InvokeAsync(step)">
                @if (isCompleted && !isCurrent)
                {
                    <span>✓</span>
                }
                else
                {
                    @step
                }
            </button>
            <div class="small mt-1 @(isCurrent ? "fw-bold" : isCompleted ? "" : "text-muted")">
                @stepNames[i]
            </div>
        </div>

        @if (i < stepNames.Length - 1)
        {
            <div class="flex-fill d-flex align-items-center" style="margin-top:-1.2rem;">
                <hr class="w-100 @(CompletedSteps.Contains(step) ? "border-success" : "")" />
            </div>
        }
    }
</div>

